import 'package:flutter/material.dart';
import 'package:intl/intl.dart';
import '../models/finance_models.dart';
import '../services/database_service.dart';
import '../services/finance_calculator.dart';

class CostsScreen extends StatefulWidget { const CostsScreen({super.key}); @override State<CostsScreen> createState()=>_CostsScreenState(); }
class _CostsScreenState extends State<CostsScreen> {
 List<StockCost> costs=[]; bool loading=true;
 @override void initState(){super.initState();load();}
 Future<void> load() async {final v=await DatabaseService.instance.stockCosts();if(mounted)setState((){costs=v;loading=false;});}
 Future<void> add() async {final item=TextEditingController(),qty=TextEditingController(),unit=TextEditingController(),note=TextEditingController();String kind='adjustment';final ok=await showDialog<bool>(context:context,builder:(d)=>StatefulBuilder(builder:(d,s)=>AlertDialog(title:const Text('Add stock cost / COGS entry'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:item,decoration:const InputDecoration(labelText:'Item / SKU')),TextField(controller:qty,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Quantity issued / adjusted')),TextField(controller:unit,keyboardType:const TextInputType.numberWithOptions(decimal:true),decoration:const InputDecoration(labelText:'Unit cost (₹)')),DropdownButtonFormField<String>(value:kind,items:const[DropdownMenuItem(value:'purchase',child:Text('Purchase / restock')),DropdownMenuItem(value:'opening',child:Text('Opening cost')),DropdownMenuItem(value:'adjustment',child:Text('Issued / sold adjustment'))],onChanged:(v)=>s(()=>kind=v??'adjustment')),TextField(controller:note,decoration:const InputDecoration(labelText:'Note'))])),actions:[TextButton(onPressed:()=>Navigator.pop(d,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(d,true),child:const Text('Save'))])));final q=double.tryParse(qty.text),u=double.tryParse(unit.text);if(ok==true&&item.text.trim().isNotEmpty&&q!=null&&q>0&&u!=null&&u>=0){await DatabaseService.instance.addStockCost(StockCost(id:null,date:DateTime.now(),item:item.text.trim(),quantity:q,unitCost:u,kind:kind,note:note.text));await load();}item.dispose();qty.dispose();unit.dispose();note.dispose();}
 @override Widget build(BuildContext c){final total=costs.where((x)=>x.kind=='adjustment').fold<double>(0,(s,x)=>s+x.totalCost.abs());return Scaffold(appBar:AppBar(title:const Text('COGS & stock costs'),actions:[IconButton(onPressed:load,icon:const Icon(Icons.refresh))]),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add cost entry')),body:loading?const Center(child:CircularProgressIndicator()):ListView(padding:const EdgeInsets.all(16),children:[Card(child:Padding(padding:const EdgeInsets.all(16),child:Column(crossAxisAlignment:CrossAxisAlignment.start,children:[const Text('Recorded COGS adjustments',style:TextStyle(color:Colors.blueGrey)),const SizedBox(height:6),Text(FinanceCalculator.money(total),style:const TextStyle(fontSize:26,fontWeight:FontWeight.w800)),const SizedBox(height:6),const Text('This total reflects entries marked issued / sold adjustment. Purchases and opening balances are retained separately. It is not a perpetual-inventory calculation.')]))),Text('${costs.length} stock-cost entries',style:Theme.of(c).textTheme.titleMedium),...costs.map((x)=>Card(child:ListTile(title:Text(x.item),subtitle:Text('${x.kind} • ${DateFormat('dd MMM yyyy').format(x.date)} • Qty ${x.quantity} × ${FinanceCalculator.money(x.unitCost)}'),trailing:Text(FinanceCalculator.money(x.totalCost),style:const TextStyle(fontWeight:FontWeight.w700))))) ]));}
}
